// === Значки разделов и нижнего меню в облике Abacus (PROTOCOL §20) ===
//
// Атрибуция выше — legal-комментарий «/*!»: лицензия значков (CC BY 4.0)
// требует её в том, что уходит людям, а минификатор Vite вырезает все
// комментарии, кроме legal, и те — только с comments.legal в vite.config.ts.
//
// Abacus нарисовал разделы значками Font Awesome: неактивная вкладка — контур
// (regular), активная — тот же значок залитым (solid), 19px. Пути перенесены
// 1:1 из @fortawesome/fontawesome-free@6.5.1 (svgs/), без зависимости: два
// десятка путей — не повод тянуть пакет.
//
// Рисунок залит, а не обведён: вес провайдера ему не нужен, но glyph() всё
// равно ставит strokeWidth — и метрика icons.spec видит обычный значок.
// Высота em шрифта (512) → 22.8 единицы сетки 24: при ICON.header значок
// выходит 19px, ровно как в макете. Облачка шире квадрата (640 из 512) и
// выступают за поле на 2.25 единицы с боков — поэтому overflow visible.
const FA_EM = 22.8 / 512;
function fa(name: string, width: number, d: string): LucideIcon {
  const tx = (24 - width * FA_EM) / 2;
  const ty = (24 - 512 * FA_EM) / 2;
  return glyph(
    name,
    <path d={d} transform={`translate(${tx} ${ty}) scale(${FA_EM})`} fill="currentColor" stroke="none" />,
    width > 512 ? { style: { overflow: 'visible' } } : undefined,
  );
}

